window.search = Object.assign(window.search, JSON.parse('{"results_options":{"limit_results":30,"teaser_word_count":30},"search_options":{"bool":"OR","expand":true,"fields":{"body":{"boost":1},"breadcrumbs":{"boost":1},"title":{"boost":2}}},"doc_urls":["intro.html","people.html#народ","people.html#физиологичното-родство","people.html#обща-земя","people.html#обща-религия","people.html#общ-език"],"index":{"fields":["title","body","breadcrumbs"],"pipeline":["trimmer","stopWordFilter","stemmer"],"ref":"id","version":"0.9.5","index":{"body":{"root":{"docs":{},"df":0,"c":{"docs":{},"df":0,"a":{"docs":{},"df":0,"t":{"docs":{},"df":0,"h":{"docs":{},"df":0,"r":{"docs":{},"df":0,"i":{"docs":{},"df":0,"e":{"docs":{},"df":0,"n":{"docs":{"5":{"tf":1.0}},"df":1}}}}}}}},"e":{"docs":{"2":{"tf":1.0}},"df":1},"r":{"docs":{},"df":0,"e":{"docs":{},"df":0,"l":{"docs":{},"df":0,"i":{"docs":{},"df":0,"g":{"docs":{},"df":0,"i":{"docs":{},"df":0,"o":{"docs":{"4":{"tf":1.0}},"df":1}}}}}}}}},"breadcrumbs":{"root":{"docs":{},"df":0,"c":{"docs":{},"df":0,"a":{"docs":{},"df":0,"t":{"docs":{},"df":0,"h":{"docs":{},"df":0,"r":{"docs":{},"df":0,"i":{"docs":{},"df":0,"e":{"docs":{},"df":0,"n":{"docs":{"5":{"tf":1.0}},"df":1}}}}}}}},"e":{"docs":{"2":{"tf":1.0}},"df":1},"r":{"docs":{},"df":0,"e":{"docs":{},"df":0,"l":{"docs":{},"df":0,"i":{"docs":{},"df":0,"g":{"docs":{},"df":0,"i":{"docs":{},"df":0,"o":{"docs":{"4":{"tf":1.0}},"df":1}}}}}}}}},"title":{"root":{"docs":{},"df":0}}},"documentStore":{"save":true,"docs":{"0":{"body":"Обект на нашето изследване е държавата; предмет на нашата наука са законите, по които държавата се явява, живее, променя се и изчезва. Общото учение за държавата е теоретична, обяснителна и нормативна духовна наука. Тя е теоретична, защото дири и установява трайните закони на държавния живот; тя е обяснителна, защото ни открива каузалната (причинната) връзка между явленията; тя е нормативна, защото ни сочи целите на държавата. Държавата е обединено в народ общество, заседнало на дадена територия и подчинено на една самопроизводна, суверенна и принудителна власт. Любомир Владикин","breadcrumbs":"Увод","id":"0","title":"Увод"},"1":{"body":"Думата народ представлява три различни понятия: население (статистическо понятие) Хората, които населяват дадена държава, включително временно пребиваващи чужденци. народност (културно понятие) Етическа принадлежност, без значение от местоположението. Например българите\\nи на територията на България, и на териториите на поробените земи или разпръснати\\nв други държави. поданство (юридическо понятие) Изключва временно пребиваващите чужденци, но включва поданиците в странство.\\nНапример сред българските поданици попадат различни народности (турци, евреи, арменци и т.н.),\\nкоито знаят, че не са и не се чувстват българи. Съществени предпоставки за нация:","breadcrumbs":"Народ » Народ","id":"1","title":"Народ"},"2":{"body":"Старото схващане e принадлежността към една и съща раса дори към едно и също племе следва да е първото условие за образуването на една народност, но общият произход от един и същ праотец обуславят племето и расата, но не и нацията, която е преди всичко не кръвна, а духовно общност, и няма нито една расово и племенно напълно чиста нация - след Великото преселение на народите, след обширните завоевания и големи колонизации с физиологическа чистота не може да се похвали нито една културна нация на света. Все пак в основата на всяка нация стои една племенна ядка. Основателно говорим за национален характер, който в основата си има и една физиологическа и биологична общност.\\nКолкото по-смесена е на една нация, колкото по несъвършен е процесът на претопяването, толкова по-неустановен е националният характер. Общият племенен произход може да бъде засилен, ако не физиологически, поне духовно, чрез засилване на вярата, че всички са родени с неразривната връзка на племенно-кръвния произход.","breadcrumbs":"Народ » Физиологичното родство","id":"2","title":"Физиологичното родство"},"3":{"body":"Влиянието на географските особености върху душата и тялото на жителя е безспорно: планинци поляци и крайморци; северняци и южняци; живеещите плодородни и бедни местности - разлики както в характера, така и физически. Еднаквите природни условия създават еднакъв начин на живот, нрави, обичаи, закони и културни ценности.\\nНо териториалната общност е имала значение за образуването на нациите много повече в миналото, отколкото сега.\\nВъв всеки случай влиянието на особеностите на територията не бива нито да се наценява, нито да се взема усамотено.","breadcrumbs":"Народ » Обща земя","id":"3","title":"Обща земя"},"4":{"body":"Духовните връзки са по-силни от физическите.\\nМежду тях исторически първо място заема религията ( religio → свързвам).\\nРелигията помага на една народност да се съпротивлява на асимилацията.","breadcrumbs":"Народ » Обща религия","id":"4","title":"Обща религия"},"5":{"body":"Езикът е най-яркият белег на националното единство, най-ценният паметник на националния гений.\\nЕзик и национална култура са корелати. Еднаквостта на езика е белег за еднаквост в начина на мислене, в отношението към света и в целия духовен склад. Езикът е най-здравата връзка, която свързва членовете на една народност в една културна общност. За съжаление, ръждата на чуждиците продължава да разлага българския език език крайно последователно (б.ред.). „Върху какво - пише Cathrien - една държава би могла да основе правото си да отнеме с насилие от една нация нейните народностни особености, да я осъди на национална смърт? Някои отговарят: върху общественото благо или държавния интерес! Неоснователно. Всички народи считат своите народностни нрави и институти, и особено своя език, за най-скъпи, върховни блага. С невероятна любов и упоритост всички народи държат на тези национални богатства и ги пазят като свещени завети на дедите си. Кой не знае как вълшебно звучи майчиният език в чужбина?\\nМоже ли държавната власт да има правото да откъсне от една нация това незаменимо съкровище? Само в името на „държавния интерес“ това не може да се извърши; защото, ако признаем на едно правителство всевластието да обсебва всички блага и права на поданиците си, винаги, щом държавният интерес изисква това, би значело да се признае, че правителството е тираническо и че гледа на поданиците като на роби.“","breadcrumbs":"Народ » Общ език","id":"5","title":"Общ език"}},"docInfo":{"0":{"body":0,"breadcrumbs":0,"title":0},"1":{"body":0,"breadcrumbs":0,"title":0},"2":{"body":1,"breadcrumbs":0,"title":0},"3":{"body":0,"breadcrumbs":0,"title":0},"4":{"body":1,"breadcrumbs":0,"title":0},"5":{"body":1,"breadcrumbs":0,"title":0}},"length":6},"lang":"English"}}'));